window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-811eafdb4e737c7f"]={"versions": [{"id": "FIG-811eafdb4e737c7f", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).</li>\n<li><strong>Technischer Zweck:</strong> Veranschaulichung des Entkopplungs- und Abfrageszenarios für synchronisierte Zeitbasen innerhalb der AUTOSAR Adaptive Platform (AP). Es stellt dar, wie eine <code>Adaptive Application</code> über den lokalen Time-Synchronization-Slave eine standardisierte Zeitbasis abfragt, während die Zeitsynchronisation über das Netzwerk (<code>sync()</code>) transparent im Hintergrund durch den Time-Synchronization-Functional-Cluster abgewickelt wird.</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR AP Foundation / Services – Functional Cluster <em>Time Synchronization</em> (<code>ara::ts</code> gemäß SWS Time Synchronization).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Entitäten / Lifelines:</strong></li>\n<li><code>:Adaptive Application</code>: Anwendungsinstanz im User Space (POSIX-Prozess), agiert als Konsument der synchronisierten Zeit.</li>\n<li><code>«aapFunctionalCluster» Slave: Time Synchronization</code>: Instanz des Functional Clusters Time Synchronization auf der lokalen Adaptive Platform Machine in der Rolle des Time Slaves (lokaler Provider der Zeitbasis).</li>\n<li><code>«aapFunctionalCluster» Master: Time Synchronization</code>: Zeitgebende Entität (Time Master) im Bordnetz (kann auf einer entfernten Classic- oder Adaptive-ECU liegen, z. B. Grandmaster Clock).</li>\n<li><strong>Stereotypen:</strong></li>\n<li><code>«aapFunctionalCluster»</code>: Kennzeichnet die architektonische Kernkomponente der AUTOSAR Adaptive Platform Architecture (AAP).</li>\n<li><strong>Schnittstellen & Interaktionspunkte:</strong></li>\n<li><code>sync()</code>: Netzwerkbasierte Synchronisationsnachricht / Protokollinteraktion (z. B. gPTP / IEEE 802.1AS über Ethernet oder CAN-TSyn / FlexRay-TSyn).</li>\n<li><code>GetCurrentTime()</code>: Synchroner API-Methodenaufruf der ARA-Schnittstelle (<code>ara::ts</code>), über den die Applikation den aktuellen Zeitstempel (inkl. Status / Synchronisationsgüte) der referenzierten Zeitbasis anfordert.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Asynchrone Hintergrund-Synchronisation (<code>sync()</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <code>Master: Time Synchronization</code> übermittelt zyklisch oder ereignisgesteuert Synchronisationsmeldungen (<code>sync()</code>) an den <code>Slave: Time Synchronization</code>.</li>\n<li>Der Slave korrigiert lokal Drift und Offset der Hardware-/OS-Clocks, aktualisiert die interne Zeitbasis und führt die Zustandsverwaltung (z. B. Synchronisationsstatus, Timeout-Überwachung).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Applikative Zeitabfrage (<code>GetCurrentTime()</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die <code>:Adaptive Application</code> triggert synchron den Aufruf <code>GetCurrentTime()</code> am lokalen <code>Slave: Time Synchronization</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Ergebnisrückgabe:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der lokale Functional Cluster liest die aktuelle extrapolierte/korrigierte Zeit aus und liefert das Zeitergebnis (Zeitstempel bzw. <code>ara::core::Result&lt;ara::ts::TimeStamp&gt;</code>) unmittelbar per Return-Pfeil an die Applikation zurück.</li>\n<li>Keine direkte Blockierung durch laufende Netzwerkübertragungen; Abfrage erfolgt entkoppelt vom Netzwerkzyklus auf Basis des lokalen Schätz-/Regelungszustands.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>API-Design (<code>ara::ts</code>):</strong> Der Zugriff auf die Zeitbasis erfolgt nicht über direkte OS-Systemaufrufe (<code>clock_gettime</code>), sondern über die typisierten C++-Klassen von <code>ara::ts</code> (z. B. abgeleitet von <code>std::chrono::Clock</code>-Konzepten bzw. spezifischen TimeBase-Klassen), um synchronisierte automobile Zeitdomänen abzubilden.</li>\n<li><strong>Fehlerbehandlung & Synchronisationsstatus:</strong> <code>GetCurrentTime()</code> liefert neben Nanosekunden-Zeitwerten Metadaten über den Status der Zeitbasis (z. B. <code>TIMEOUT</code>, <code>SYNC</code>, <code>UNSYNC</code>). Applikationsentwickler müssen prüfen, ob die Zeitbasis aktuell als synchronisiert gilt, bevor zeitkritische Aktionen (z. B. Sensorfusion, Event-Logging) ausgeführt werden.</li>\n<li><strong>Laufzeitverhalten & Performance:</strong> Der Aufruf von <code>GetCurrentTime()</code> ist für deterministische, latenzarme Ausführung ausgelegt. Er greift auf lokale Interpolationsregister/OS-Timer zu und wartet nicht auf die nächste <code>sync()</code>-PDU des Netzwerks.</li>\n<li><strong>Konfiguration (Manifest):</strong> Die Zuordnung der Applikation zu einer konkreten Zeitbasis (z. B. Global Time Base, Pure Local Time Base) wird deklarativ im Execution- und Service-Instance-Manifest modelliert.</li>\n</ul>"}, {"id": "FIG-b2f2473ecd40a79e", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).</li>\n<li><strong>Technischer Zweck:</strong> Veranschaulichung des Entkopplungs- und Abfrageszenarios für synchronisierte Zeitbasen innerhalb der AUTOSAR Adaptive Platform (AP). Es stellt dar, wie eine <code>Adaptive Application</code> über den lokalen Time-Synchronization-Slave eine standardisierte Zeitbasis abfragt, während die Zeitsynchronisation über das Netzwerk (<code>sync()</code>) transparent im Hintergrund durch den Time-Synchronization-Functional-Cluster abgewickelt wird.</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR AP Foundation / Services – Functional Cluster <em>Time Synchronization</em> (<code>ara::ts</code> gemäß SWS Time Synchronization).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Entitäten / Lifelines:</strong></li>\n<li><code>:Adaptive Application</code>: Anwendungsinstanz im User Space (POSIX-Prozess), agiert als Konsument der synchronisierten Zeit.</li>\n<li><code>«aapFunctionalCluster» Slave: Time Synchronization</code>: Instanz des Functional Clusters Time Synchronization auf der lokalen Adaptive Platform Machine in der Rolle des Time Slaves (lokaler Provider der Zeitbasis).</li>\n<li><code>«aapFunctionalCluster» Master: Time Synchronization</code>: Zeitgebende Entität (Time Master) im Bordnetz (kann auf einer entfernten Classic- oder Adaptive-ECU liegen, z. B. Grandmaster Clock).</li>\n<li><strong>Stereotypen:</strong></li>\n<li><code>«aapFunctionalCluster»</code>: Kennzeichnet die architektonische Kernkomponente der AUTOSAR Adaptive Platform Architecture (AAP).</li>\n<li><strong>Schnittstellen & Interaktionspunkte:</strong></li>\n<li><code>sync()</code>: Netzwerkbasierte Synchronisationsnachricht / Protokollinteraktion (z. B. gPTP / IEEE 802.1AS über Ethernet oder CAN-TSyn / FlexRay-TSyn).</li>\n<li><code>GetTimeWithStatus(): SynchronizedTimeBaseStatus</code>: Synchroner API-Methodenaufruf der ARA-Schnittstelle (<code>ara::ts</code>), über den die Applikation die Zeit samt explizitem Status (<code>SynchronizedTimeBaseStatus</code>) der referenzierten Zeitbasis anfordert.</li>\n<li><code>GetCreationTime()</code>: Synchroner API-Methodenaufruf zur Abfrage des Erstellungszeitpunkts der Zeitbasis.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Asynchrone Hintergrund-Synchronisation (<code>sync()</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <code>Master: Time Synchronization</code> übermittelt zyklisch oder ereignisgesteuert Synchronisationsmeldungen (<code>sync()</code>) an den <code>Slave: Time Synchronization</code>.</li>\n<li>Der Slave korrigiert lokal Drift und Offset der Hardware-/OS-Clocks, aktualisiert die interne Zeitbasis und führt die Zustandsverwaltung (z. B. Synchronisationsstatus, Timeout-Überwachung).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Applikative Zeitabfrage (<code>GetTimeWithStatus()</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die <code>:Adaptive Application</code> triggert synchron den Aufruf <code>GetTimeWithStatus(): SynchronizedTimeBaseStatus</code> am lokalen <code>Slave: Time Synchronization</code>.</li>\n<li>Der lokale Functional Cluster liefert das Zeitergebnis zusammen mit dem Synchronisationsstatus per Return-Pfeil an die Applikation zurück.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abfrage der Erstellungszeit (<code>GetCreationTime()</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die <code>:Adaptive Application</code> ruft nachfolgend synchron <code>GetCreationTime()</code> am lokalen <code>Slave: Time Synchronization</code> auf.</li>\n<li>Der Slave liefert den Erstellungszeitstempel der Zeitbasis per Return-Pfeil an die Applikation zurück.</li>\n<li>Sämtliche Abfragen erfolgen entkoppelt vom Netzwerkzyklus auf Basis des lokalen Zustands.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>API-Design (<code>ara::ts</code>):</strong> Der Zugriff auf die Zeitbasis erfolgt nicht über direkte OS-Systemaufrufe (<code>clock_gettime</code>), sondern über die typisierten Schnittstellen von <code>ara::ts</code>. Die API differenziert zwischen der statusbehafteten Zeitabfrage (<code>GetTimeWithStatus()</code>) und der Abfrage des Ursprungszeitpunkts (<code>GetCreationTime()</code>).</li>\n<li><strong>Fehlerbehandlung & Synchronisationsstatus:</strong> <code>GetTimeWithStatus()</code> liefert über den Rückgabetyp <code>SynchronizedTimeBaseStatus</code> explizite Informationen über die Güte und Gültigkeit der Zeitbasis (z. B. Synchronisationszustand, Timeout-Status oder Drift).</li>\n</ul>"}, {"id": "FIG-c0a9744e0695be48", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).</li>\n<li><strong>Technischer Zweck:</strong> Veranschaulichung des Entkopplungs- und Abfrageszenarios für synchronisierte Zeitbasen innerhalb der AUTOSAR Adaptive Platform (AP). Es stellt dar, wie eine <code>Adaptive Application</code> über den lokalen Time-Synchronization-Slave eine standardisierte Zeitbasis abfragt, während die Zeitsynchronisation über das Netzwerk (<code>sync()</code>) transparent im Hintergrund durch den Time-Synchronization-Functional-Cluster abgewickelt wird.</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR AP Foundation / Services – Functional Cluster <em>Time Synchronization</em> (<code>ara::ts</code> gemäß SWS Time Synchronization).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Entitäten / Lifelines:</strong></li>\n<li><code>:Adaptive Application</code>: Anwendungsinstanz im User Space (POSIX-Prozess), agiert als Konsument der synchronisierten Zeit.</li>\n<li><code>«aapFunctionalCluster» Slave: Time Synchronization</code>: Instanz des Functional Clusters Time Synchronization auf der lokalen Adaptive Platform Machine in der Rolle des Time Slaves (lokaler Provider der Zeitbasis).</li>\n<li><code>«aapFunctionalCluster» Master: Time Synchronization</code>: Zeitgebende Entität (Time Master) im Bordnetz (kann auf einer entfernten Classic- oder Adaptive-ECU liegen, z. B. Grandmaster Clock).</li>\n<li><strong>Stereotypen:</strong></li>\n<li><code>«aapFunctionalCluster»</code>: Kennzeichnet die architektonische Kernkomponente der AUTOSAR Adaptive Platform Architecture (AAP).</li>\n<li><strong>Schnittstellen & Interaktionspunkte:</strong></li>\n<li><code>sync()</code>: Netzwerkbasierte Synchronisationsnachricht / Protokollinteraktion (z. B. gPTP / IEEE 802.1AS über Ethernet oder CAN-TSyn / FlexRay-TSyn).</li>\n<li><code>GetTimeWithStatus(): SynchronizedTimeBaseStatus</code>: Synchroner API-Methodenaufruf der ARA-Schnittstelle (<code>ara::ts</code>), über den die Applikation die Zeit samt explizitem Status (<code>SynchronizedTimeBaseStatus</code>) der referenzierten Zeitbasis anfordert.</li>\n<li><code>GetCreationTime()</code>: Synchroner API-Methodenaufruf zur Abfrage des Erstellungszeitpunkts der Zeitbasis.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Asynchrone Hintergrund-Synchronisation (<code>sync()</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <code>Master: Time Synchronization</code> übermittelt zyklisch oder ereignisgesteuert Synchronisationsmeldungen (<code>sync()</code>) an den <code>Slave: Time Synchronization</code>.</li>\n<li>Der Slave korrigiert lokal Drift und Offset der Hardware-/OS-Clocks, aktualisiert die interne Zeitbasis und führt die Zustandsverwaltung (z. B. Synchronisationsstatus, Timeout-Überwachung).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Applikative Zeitabfrage (<code>GetTimeWithStatus()</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die <code>:Adaptive Application</code> triggert synchron den Aufruf <code>GetTimeWithStatus(): SynchronizedTimeBaseStatus</code> am lokalen <code>Slave: Time Synchronization</code>.</li>\n<li>Der lokale Functional Cluster liefert das Zeitergebnis zusammen mit dem Synchronisationsstatus per Return-Pfeil an die Applikation zurück.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abfrage der Erstellungszeit (<code>GetCreationTime()</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die <code>:Adaptive Application</code> ruft nachfolgend synchron <code>GetCreationTime()</code> am lokalen <code>Slave: Time Synchronization</code> auf.</li>\n<li>Der Slave liefert den Erstellungszeitstempel der Zeitbasis per Return-Pfeil an die Applikation zurück.</li>\n<li>Sämtliche Abfragen erfolgen entkoppelt vom Netzwerkzyklus auf Basis des lokalen Zustands.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>API-Design (<code>ara::ts</code>):</strong> Der Zugriff auf die Zeitbasis erfolgt nicht über direkte OS-Systemaufrufe (<code>clock_gettime</code>), sondern über die typisierten Schnittstellen von <code>ara::ts</code>. Die API differenziert zwischen der statusbehafteten Zeitabfrage (<code>GetTimeWithStatus()</code>) und der Abfrage des Ursprungszeitpunkts (<code>GetCreationTime()</code>).</li>\n<li><strong>Fehlerbehandlung & Synchronisationsstatus:</strong> <code>GetTimeWithStatus()</code> liefert über den Rückgabetyp <code>SynchronizedTimeBaseStatus</code> explizite Informationen über die Güte und Gültigkeit der Zeitbasis (z. B. Synchronisationszustand, Timeout-Status oder Drift).</li>\n</ul>"}], "trans": [{"from": "FIG-811eafdb4e737c7f", "to": "FIG-b2f2473ecd40a79e", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>GetCurrentTime()</code>: Die synchrone Abfragemethode der <code>:Adaptive Application</code> an den <code>Slave: Time Synchronization</code> wurde entfernt.</li>\n<li><code>GetTimeWithStatus(): SynchronizedTimeBaseStatus</code>: Neu eingeführter synchroner API-Aufruf zur Abfrage der Zeitbasis inklusive Rückgabe des Typs <code>SynchronizedTimeBaseStatus</code>.</li>\n<li><code>GetCreationTime()</code>: Neu eingeführter synchroner Methodenaufruf der <code>:Adaptive Application</code> an den <code>Slave: Time Synchronization</code> zur Abfrage der Erstellungszeit der Zeitbasis.</li>\n</ul>"}, {"from": "FIG-b2f2473ecd40a79e", "to": "FIG-c0a9744e0695be48", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
